/* Lightweight anime()-compatible animation helper for static-phase */
(function (global) {
  'use strict';

  function resolveTargets(targets) {
    if (!targets) return [];
    if (typeof targets === 'string') {
      return Array.from(document.querySelectorAll(targets));
    }
    if (Array.isArray(targets)) {
      return targets.flatMap(resolveTargets);
    }
    if (targets instanceof Element || targets === window || typeof targets === 'object') {
      return [targets];
    }
    return [];
  }

  function parseNumber(val, fallback) {
    if (typeof val === 'number' && !Number.isNaN(val)) return val;
    if (typeof val === 'string') {
      const cleaned = parseFloat(val);
      if (!Number.isNaN(cleaned)) return cleaned;
    }
    return fallback;
  }

  function easeOutCubic(t) {
    return 1 - Math.pow(1 - t, 3);
  }

  function anime(params) {
    const opts = params || {};
    const els = resolveTargets(opts.targets);
    const duration = Math.max(0, parseNumber(opts.duration, 600));
    const baseDelay = Math.max(0, parseNumber(opts.delay, 0));
    const staggerStep =
      typeof opts.delay === 'function' ? 0 : 0;

    let resolveFinished;
    const finished = new Promise((resolve) => {
      resolveFinished = resolve;
    });

    if (!els.length) {
      if (typeof opts.complete === 'function') opts.complete();
      resolveFinished();
      return { finished, pause: function () {}, play: function () {} };
    }

    const animProps = Object.keys(opts).filter(
      (k) => !['targets', 'duration', 'delay', 'easing', 'complete', 'begin', 'update'].includes(k)
    );

    let began = false;
    let paused = false;
    const startTime = performance.now();

    const itemStates = els.map((el, idx) => {
      const itemDelay =
        typeof opts.delay === 'function' ? Math.max(0, opts.delay(el, idx, els.length)) : baseDelay + idx * staggerStep;
      const props = {};

      animProps.forEach((prop) => {
        const raw = opts[prop];
        if (Array.isArray(raw)) {
          props[prop] = {
            from: parseNumber(raw[0], 0),
            to: parseNumber(raw[1], parseNumber(raw[0], 0))
          };
        } else {
          const currentVal =
            prop === 'opacity' && el.style
              ? parseNumber(el.style.opacity, 1)
              : 0;
          props[prop] = {
            from: currentVal,
            to: parseNumber(raw, currentVal)
          };
        }
      });

      return { el, itemDelay, props, done: false };
    });

    let rafId = 0;

    function applyFrame(now) {
      if (paused) {
        rafId = requestAnimationFrame(applyFrame);
        return;
      }

      if (!began) {
        began = true;
        if (typeof opts.begin === 'function') opts.begin();
      }

      let allDone = true;

      itemStates.forEach((item) => {
        const elapsed = now - startTime - item.itemDelay;
        if (elapsed < 0) {
          allDone = false;
          return;
        }

        const rawT = duration === 0 ? 1 : Math.min(1, elapsed / duration);
        const easedT = easeOutCubic(rawT);

        let tx = 0;
        let ty = 0;
        let scale = 1;

        Object.keys(item.props).forEach((prop) => {
          const { from, to } = item.props[prop];
          const val = from + (to - from) * easedT;

          if (prop === 'opacity' && item.el.style) {
            item.el.style.opacity = String(val);
          } else if (prop === 'translateX') {
            tx = val;
          } else if (prop === 'translateY') {
            ty = val;
          } else if (prop === 'scale') {
            scale = val;
          } else if (prop in item.el) {
            item.el[prop] = val;
          }
        });

        if (item.el.style && (tx !== 0 || ty !== 0 || scale !== 1)) {
          item.el.style.transform = `translate3d(${tx}px, ${ty}px, 0) scale(${scale})`;
        }

        if (rawT < 1) {
          allDone = false;
        } else {
          item.done = true;
        }
      });

      if (typeof opts.update === 'function') opts.update();

      if (!allDone) {
        rafId = requestAnimationFrame(applyFrame);
      } else {
        if (typeof opts.complete === 'function') opts.complete();
        resolveFinished();
      }
    }

    rafId = requestAnimationFrame(applyFrame);

    return {
      finished,
      pause: function () {
        paused = true;
      },
      play: function () {
        paused = false;
      }
    };
  }

  anime.stagger = function (val) {
    const step = parseNumber(val, 60);
    return function (_el, i) {
      return i * step;
    };
  };

  global.anime = anime;
})(typeof window !== 'undefined' ? window : this);